B.NP={press_banca:0,press_inclinado_mancuerna:1,aperturas_polea:2,fondos:3,dominadas:4,remo_barra:5,jalon_polea:6,remo_mancuerna:7,peso_muerto:8,press_militar:9,elevaciones_laterales:10,pajaro:11,curl_barra:12,curl_martillo:13,extension_triceps_polea:14,press_frances:15,curl_muneca:16,sentadilla:17,prensa:18,zancadas:19,curl_femoral:20,elevacion_talones:21,plancha:22,elevacion_piernas:23,rueda_abdominal:24,flexiones:25,flexiones_diamante:26,sentadilla_goblet:27,sentadilla_libre:28,peso_muerto_rumano:29,press_hombro_mancuerna:30,curl_mancuerna:31,extension_triceps_mancuerna:32,remo_banda:33,puente_gluteo:34,talones_libre:35,crunch:36,flexiones_rodillas:37,flexiones_inclinadas:38,flexiones_declinadas:39,remo_mesa:40,superman:41,remo_garrafa:42,flexiones_pica:43,press_banda:44,elevaciones_botellas:45,curl_banda:46,curl_garrafa:47,fondos_silla:48,curl_muneca_garrafa:49,paseo_granjero:50,escaladores:51,tijeras:52,zancada_atras:53,sentadilla_bulgara:54,sentadilla_pared:55,subida_escalon:56,sentadilla_salto:57,puente_una_pierna:58,talones_una_pierna:59,saltitos:60,saltos_tijera:61}
B.aCp=s(["T\xfambate con los ojos bajo la barra y los pies firmes en el suelo.","Junta las esc\xe1pulas y agarra un poco m\xe1s ancho que los hombros.","Baja controlado hasta rozar el pecho, a la altura del estern\xf3n.","Empuja hacia arriba y un poco hacia atr\xe1s hasta estirar los brazos."],t.s)
B.axB=s(["Rebotar la barra en el pecho.","Despegar la cadera del banco."],t.s)
B.anw=new A.cl(B.aCp,B.axB,"Suelta el aire al subir o empujar.")
B.azt=s(["Banco a 30\u201345\xb0. Mancuernas a la altura del pecho alto.","Codos a unos 45\xb0 del cuerpo, no abiertos en cruz.","Empuja hasta casi juntar las mancuernas arriba.","Baja lento hasta sentir el estiramiento del pecho."],t.s)
B.ayw=s(["Inclinar demasiado el banco (trabaja m\xe1s el hombro)."],t.s)
B.aog=new A.cl(B.azt,B.ayw,"Suelta el aire al subir o empujar.")
B.axt=s(["Poleas altas, un pie adelantado y el pecho erguido.","Codos ligeramente doblados durante todo el recorrido.","Cierra los brazos en arco hasta juntar las manos delante.","Vuelve despacio hasta sentir el pecho estirado."],t.s)
B.auc=s(["Convertirlo en un press doblando los codos."],t.s)
B.aod=new A.cl(B.axt,B.auc,"Suelta el aire al subir o empujar.")
B.aGQ=s(["Sube a las paralelas con los brazos estirados y hombros abajo.","Inclina un poco el torso hacia delante.","Baja hasta que los codos lleguen a unos 90\xb0.","Empuja hasta estirar los brazos sin bloquear de golpe."],t.s)
B.aym=s(["Bajar demasiado si te molesta el hombro.","Encoger los hombros hacia las orejas."],t.s)
B.aob=new A.cl(B.aGQ,B.aym,"Suelta el aire al subir o empujar.")
B.aFf=s(["Cu\xe9lgate con agarre algo m\xe1s ancho que los hombros.","Baja los hombros y aprieta el abdomen antes de tirar.","Tira llevando los codos hacia las costillas hasta pasar la barbilla.","Baja completo y controlado, sin soltarte de golpe."],t.s)
B.avJ=s(["Balancearse para ayudarse.","Hacer medias repeticiones."],t.s)
B.anG=new A.cl(B.aFf,B.avJ,"Suelta el aire al subir.")
B.aEp=s(["Rodillas un poco flexionadas, torso inclinado unos 45\xb0 y espalda recta.","La barra cuelga bajo los hombros.","Tira hacia el ombligo llevando los codos atr\xe1s.","Aprieta la espalda arriba un instante y baja controlado."],t.s)
B.aAZ=s(["Redondear la espalda.","Levantar el torso para tirar."],t.s)
B.anX=new A.cl(B.aEp,B.aAZ,"Suelta el aire al subir o empujar.")
B.avN=s(["Si\xe9ntate con los muslos fijos bajo el apoyo.","Agarra ancho y saca un poco el pecho.","Tira de la barra hacia la parte alta del pecho.","Sube despacio hasta estirar los brazos."],t.s)
B.aGy=s(["Tirar detr\xe1s de la nuca.","Echarse muy atr\xe1s para mover m\xe1s peso."],t.s)
B.ao3=new A.cl(B.avN,B.aGy,"Suelta el aire al subir o empujar.")
B.aAD=s(["Apoya una mano y una rodilla en el banco, espalda plana.","La mancuerna cuelga bajo el hombro.","Tira llevando el codo hacia la cadera.","Baja hasta estirar el brazo por completo."],t.s)
B.awO=s(["Girar el torso para subir m\xe1s."],t.s)
B.aoo=new A.cl(B.aAD,B.awO,"Suelta el aire al subir o empujar.")
B.aBp=s(["Barra sobre la mitad del pie, espinillas casi toc\xe1ndola.","Cadera atr\xe1s, espalda recta y pecho arriba al agarrar.","Empuja el suelo con las piernas: la barra sube pegada al cuerpo.","Termina erguido, apretando gl\xfateos, sin echarte atr\xe1s."],t.s)
B.av8=s(["Redondear la espalda baja.","Alejar la barra del cuerpo."],t.s)
B.aok=new A.cl(B.aBp,B.av8,"Suelta el aire al subir o empujar.")
B.aGc=s(["De pie, barra a la altura de las clav\xedculas, abdomen y gl\xfateos firmes.","Empuja recto hacia arriba apartando un poco la cabeza.","Arriba, mete la cabeza entre los brazos.","Baja controlado hasta las clav\xedculas."],t.s)
B.aDN=s(["Arquear la espalda baja.","Empujar la barra hacia delante."],t.s)
B.aoh=new A.cl(B.aGc,B.aDN,"Suelta el aire al subir o empujar.")
B.au6=s(["De pie, mancuernas a los lados y codos un poco doblados.",u.Y,"Imagina que empujas las paredes, no que subes las manos.","Baja lento, sin dejarlas caer."],t.s)
B.axw=s(["Balancear el cuerpo.","Subir los hombros hacia las orejas."],t.s)
B.anC=new A.cl(B.au6,B.axw,"Suelta el aire al subir o empujar.")
B.aub=s(["Inclina el torso casi paralelo al suelo con la espalda recta.","Mancuernas colgando, codos un poco doblados.","Abre los brazos hacia los lados apretando la parte de atr\xe1s del hombro.","Baja controlado."],t.s)
B.aCr=s(["Juntar las esc\xe1pulas en vez de mover los brazos."],t.s)
B.anZ=new A.cl(B.aub,B.aCr,"Suelta el aire al subir o empujar.")
B.aCc=s(["De pie, barra con agarre a la anchura de los hombros.","Codos pegados al cuerpo y quietos.","Sube la barra doblando solo los codos.","Baja hasta estirar casi del todo."],t.s)
B.aEM=s(["Balancear el torso.","Adelantar los codos."],t.s)
B.anJ=new A.cl(B.aCc,B.aEM,"Suelta el aire al subir o empujar.")
B.azM=s(["Mancuernas con las palmas mir\xe1ndose, como un martillo.","Codos fijos a los lados.","Sube sin girar la mu\xf1eca.","Baja lento."],t.s)
B.aEo=s(["Ayudarse con el hombro."],t.s)
B.ao2=new A.cl(B.azM,B.aEo,"Suelta el aire al subir o empujar.")
B.aB1=s(["Frente a la polea alta, codos pegados a las costillas.","Empuja hacia abajo hasta estirar los brazos.","Aprieta el tr\xedceps abajo un instante.","Sube solo hasta que el antebrazo quede horizontal."],t.s)
B.av0=s(["Separar los codos del cuerpo.","Usar el peso del cuerpo."],t.s)
B.anQ=new A.cl(B.aB1,B.av0,"Suelta el aire al subir o empujar.")
B.aGW=s(["Tumbado, barra sobre la frente con los brazos verticales.","Baja doblando solo los codos hacia la frente o detr\xe1s de la cabeza.","Los codos apuntan al techo todo el tiempo.","Extiende hasta estirar los brazos."],t.s)
B.aG7=s(["Abrir los codos hacia los lados."],t.s)
B.ao_=new A.cl(B.aGW,B.aG7,"Suelta el aire al subir o empujar.")
B.aGJ=s(["Sentado, antebrazos sobre los muslos y mu\xf1ecas por fuera de las rodillas.","Deja que la barra baje hasta los dedos.","Sube doblando solo la mu\xf1eca.","Movimientos cortos y controlados."],t.s)
B.aG2=s(["Mover los antebrazos."],t.s)
B.anS=new A.cl(B.aGJ,B.aG2,"Suelta el aire al subir o empujar.")
B.ayg=s(["Barra sobre la parte alta de la espalda, pies a la anchura de los hombros.","Inspira, aprieta el abdomen y lleva la cadera atr\xe1s y abajo.","Rodillas en la direcci\xf3n de las puntas de los pies.","Baja hasta que el muslo quede paralelo o m\xe1s, y sube empujando el suelo."],t.s)
B.ay9=s(["Rodillas hacia dentro.","Levantar los talones.","Redondear la espalda abajo."],t.s)
B.anH=new A.cl(B.ayg,B.ay9,"Suelta el aire al subir o empujar.")
B.aGn=s(["Espalda y cadera pegadas al respaldo.","Pies en el centro de la plataforma, a la anchura de la cadera.","Baja hasta que las rodillas lleguen a unos 90\xb0.","Empuja sin bloquear las rodillas al final."],t.s)
B.aB_=s(["Despegar la cadera abajo.","Bloquear las rodillas de golpe."],t.s)
B.anY=new A.cl(B.aGn,B.aB_,"Suelta el aire al subir o empujar.")
B.aCL=s(["De pie con las mancuernas a los lados.","Da un paso largo adelante.",u.B,"Empuja con el pie de delante para volver."],t.s)
B.aD9=s(["Paso demasiado corto (la rodilla se pasa mucho)."],t.s)
B.aoc=new A.cl(B.aCL,B.aD9,"Suelta el aire al subir o empujar.")
B.azH=s(["Tumbado boca abajo, el rodillo justo encima de los talones.","Cadera pegada al banco.","Lleva los talones hacia los gl\xfateos.","Baja despacio sin dejar caer el peso."],t.s)
B.aE3=s(["Levantar la cadera para subir."],t.s)
B.anL=new A.cl(B.azH,B.aE3,"Suelta el aire al subir o empujar.")
B.aDM=s(["Puntas de los pies en el borde, talones en el aire.","Baja los talones hasta sentir el estiramiento.","Sube todo lo posible sobre las puntas.","Mant\xe9n un segundo arriba."],t.s)
B.aFS=s(["Rebotar abajo.","Doblar las rodillas."],t.s)
B.anB=new A.cl(B.aDM,B.aFS,"Suelta el aire al subir o empujar.")
B.aCv=s(["Manos (o antebrazos) bajo los hombros, cuerpo en l\xednea recta.","Aprieta abdomen y gl\xfateos.","No dejes caer ni subir la cadera.","Respira normal y aguanta el tiempo marcado."],t.s)
B.auJ=s(["Hundir la zona lumbar."],t.s)
B.aoe=new A.cl(B.aCv,B.auJ,"Respira corto y constante; no aguantes el aire.")
B.aCU=s(["Tumbado boca arriba, manos a los lados o bajo la cadera.","Piernas estiradas y juntas.","S\xfabelas hasta la vertical sin despegar la espalda baja.","B\xe1jalas despacio sin tocar el suelo."],t.s)
B.azq=s(["Arquear la espalda al bajar."],t.s)
B.ao4=new A.cl(B.aCU,B.azq,"Suelta el aire al subir o empujar.")
B.aEb=s(["De rodillas, la rueda bajo los hombros.","Aprieta el abdomen y rueda hacia delante despacio.","Llega tan lejos como puedas sin hundir la espalda.","Vuelve tirando con el abdomen, no con los brazos."],t.s)
B.aH8=s(["Dejar caer la cadera."],t.s)
B.anE=new A.cl(B.aEb,B.aH8,"Suelta el aire al subir o empujar.")
B.azQ=s(["Manos algo m\xe1s anchas que los hombros, cuerpo recto.","Baja el pecho hasta casi tocar el suelo.","Codos a unos 45\xb0 del cuerpo.","Empuja hasta estirar los brazos."],t.s)
B.azA=s(["Hundir la cadera.","Hacer medio recorrido."],t.s)
B.aol=new A.cl(B.azQ,B.azA,"Suelta el aire al subir o empujar.")
B.aG4=s(["Manos juntas bajo el pecho formando un rombo con los dedos.","Cuerpo recto de cabeza a talones.","Baja con los codos pegados al cuerpo.","Empuja con los tr\xedceps."],t.s)
B.Ib=s(["Abrir los codos."],t.s)
B.anq=new A.cl(B.aG4,B.Ib,"Suelta el aire al subir o empujar.")
B.awK=s(["Sujeta la pesa pegada al pecho con ambas manos.","Pies algo m\xe1s anchos que la cadera.","Baja entre las piernas con el pecho erguido.","Sube empujando el suelo."],t.s)
B.awy=s(["Inclinarse hacia delante."],t.s)
B.anU=new A.cl(B.awK,B.awy,"Suelta el aire al subir o empujar.")
B.aBV=s(["Pies a la anchura de los hombros, brazos al frente.","Cadera atr\xe1s y abajo, pecho arriba.","Baja hasta el paralelo o lo que permita tu movilidad.","Sube apretando gl\xfateos."],t.s)
B.avW=s(["Levantar los talones."],t.s)
B.aoi=new A.cl(B.aBV,B.avW,"Suelta el aire al subir o empujar.")
B.aD_=s(["De pie, mancuernas delante de los muslos, rodillas apenas flexionadas.","Lleva la cadera atr\xe1s manteniendo la espalda recta.","Baja las pesas pegadas a las piernas hasta sentir los isquios.","Vuelve empujando la cadera adelante."],t.s)
B.avC=s(["Doblar mucho las rodillas (se vuelve sentadilla)."],t.s)
B.anv=new A.cl(B.aD_,B.avC,"Suelta el aire al subir o empujar.")
B.aFd=s(["Mancuernas a la altura de los hombros, palmas al frente.","Abdomen firme.","Empuja hacia arriba hasta casi juntarlas.","Baja controlado."],t.s)
B.HI=s(["Arquear la espalda baja."],t.s)
B.anx=new A.cl(B.aFd,B.HI,"Suelta el aire al subir o empujar.")
B.axI=s(["Mancuernas a los lados, palmas al frente.","Codos fijos.","Sube girando ligeramente la mu\xf1eca hacia fuera.","Baja lento."],t.s)
B.aEP=s(["Balancearse."],t.s)
B.anu=new A.cl(B.axI,B.aEP,"Suelta el aire al subir o empujar.")
B.aH1=s(["Sujeta una mancuerna con ambas manos sobre la cabeza.","Baja detr\xe1s de la cabeza doblando solo los codos.","Codos apuntando al techo.","Extiende hasta estirar los brazos."],t.s)
B.aom=new A.cl(B.aH1,B.Ib,"Suelta el aire al subir o empujar.")
B.aEg=s(["Sentado, piernas estiradas y la banda alrededor de los pies.","Espalda recta y pecho arriba.","Tira llevando los codos atr\xe1s pegados al cuerpo.","Vuelve despacio sin redondear la espalda."],t.s)
B.ax0=s(["Echarse atr\xe1s con el torso."],t.s)
B.ao7=new A.cl(B.aEg,B.ax0,"Suelta el aire al subir o empujar.")
B.axT=s(["Tumbado boca arriba, rodillas dobladas y pies en el suelo.","Empuja con los talones y sube la cadera.","Arriba, el cuerpo forma una l\xednea de hombros a rodillas.","Aprieta gl\xfateos un segundo y baja."],t.s)
B.I7=s(["Arquear la espalda en vez de usar el gl\xfateo."],t.s)
B.aoa=new A.cl(B.axT,B.I7,"Suelta el aire al subir o empujar.")
B.aBi=s(["De pie en el borde de un escal\xf3n, ap\xf3yate en la pared.","Baja los talones para estirar.","Sube todo lo posible sobre las puntas.","Hazlo lento: aqu\xed la calidad lo es todo."],t.s)
B.aCf=s(["Rebotar."],t.s)
B.anV=new A.cl(B.aBi,B.aCf,"Suelta el aire al subir o empujar.")
B.aCq=s(["Tumbado, rodillas dobladas, manos en las sienes.","Despega los hombros del suelo enrollando la columna.","Mira al techo, no tires del cuello.","Baja controlado."],t.s)
B.awN=s(["Tirar de la cabeza con las manos."],t.s)
B.anP=new A.cl(B.aCq,B.awN,"Suelta el aire al subir o empujar.")
B.aCM=s(["Rodillas en el suelo (o en un coj\xedn) y manos algo m\xe1s anchas que los hombros.","Cuerpo recto de rodillas a cabeza: no dobles la cadera.","Baja el pecho hasta casi tocar el suelo.","Empuja hasta estirar los brazos."],t.s)
B.aFh=s(["Sacar el trasero hacia arriba.","Bajar solo la cabeza."],t.s)
B.aoj=new A.cl(B.aCM,B.aFh,"Suelta el aire al subir o empujar.")
B.axZ=s(["Manos en el asiento de una silla firme contra la pared, o en el sof\xe1.","Pies atr\xe1s, cuerpo recto de talones a cabeza.","Baja el pecho hasta el borde del asiento.","Empuja. Cuanto m\xe1s baja la superficie, m\xe1s dif\xedcil."],t.s)
B.aFb=s(["Usar una silla que se desliza.","Hundir la cadera."],t.s)
B.anD=new A.cl(B.axZ,B.aFb,"Suelta el aire al subir o empujar.")
B.aBY=s(["Pies sobre una silla o el sof\xe1, manos en el suelo bajo los hombros.","Abdomen y gl\xfateos firmes: el cuerpo es una tabla.","Baja hasta casi tocar el suelo con la frente por delante de las manos.","Empuja hasta estirar los brazos."],t.s)
B.aEl=s(["Dejar caer la cadera.","Abrir los codos en cruz."],t.s)
B.anI=new A.cl(B.aBY,B.aEl,"Suelta el aire al subir o empujar.")
B.aCP=s(["T\xfambate bajo una mesa ROBUSTA y agarra el borde con las dos manos.","Talones apoyados y cadera arriba, en l\xednea con los hombros.","Tira llevando el pecho hacia el borde y los codos hacia el suelo.","Baja despacio hasta estirar los brazos."],t.s)
B.aza=s(["Usar una mesa ligera o con patas plegables.","Dejar caer la cadera."],t.s)
B.anM=new A.cl(B.aCP,B.aza,"Suelta el aire al subir el pecho.")
B.aF2=s(["Boca abajo, brazos estirados al frente y piernas juntas.","Mira al suelo para no forzar el cuello.","Despega a la vez brazos, pecho y piernas unos cent\xedmetros.","Aguanta dos segundos arriba y baja con control."],t.s)
B.ay5=s(["Levantar la cabeza mirando al frente.","Subir de golpe."],t.s)
B.ao6=new A.cl(B.aF2,B.ay5,"Suelta el aire al subir o empujar.")
B.aGK=s(["Una garrafa de 5 L pesa 5 kg; una mochila con libros, lo que le metas.","Inclina el torso con la espalda recta y apoya la otra mano en una silla.","Tira llevando el codo hacia la cadera.","Baja hasta estirar el brazo y cambia de lado al acabar la serie."],t.s)
B.aHa=s(["Girar el torso para subir.","Asas que se clavan: envu\xe9lvelas en una toalla."],t.s)
B.ao1=new A.cl(B.aGK,B.aHa,"Suelta el aire al subir o empujar.")
B.awH=s(["Forma una V invertida: cadera arriba, manos y pies en el suelo.","Acerca los pies a las manos todo lo que te permita la flexibilidad.","Baja la cabeza hacia el suelo, por delante de las manos.","Empuja hasta estirar los brazos. Es un press de hombro sin pesas."],t.s)
B.aD8=s(["Bajar la cadera y convertirla en una flexi\xf3n normal."],t.s)
B.ao9=new A.cl(B.awH,B.aD8,"Suelta el aire al subir o empujar.")
B.aCu=s(["Pisa la banda con los dos pies y agarra los extremos a la altura de los hombros.","Abdomen firme y gl\xfateos apretados.","Empuja hacia arriba hasta estirar los brazos.","Baja despacio: la banda tira, no la dejes ganar."],t.s)
B.ans=new A.cl(B.aCu,B.HI,"Suelta el aire al subir o empujar.")
B.aFo=s(["Una botella de agua en cada mano (1,5 L \u2248 1,5 kg).","Codos un poco doblados y hombros lejos de las orejas.",u.Y,"Baja en tres segundos."],t.s)
B.ayG=s(["Balancear el cuerpo.","Subir m\xe1s arriba de los hombros."],t.s)
B.aon=new A.cl(B.aFo,B.ayG,"Suelta el aire al subir o empujar.")
B.aHu=s(["Pisa la banda con los pies a la anchura de la cadera.","Codos pegados al cuerpo y quietos.","Sube doblando solo los codos.","Baja despacio hasta estirar."],t.s)
B.avX=s(["Adelantar los codos.","Echarse atr\xe1s para ayudarse."],t.s)
B.anA=new A.cl(B.aHu,B.avX,"Suelta el aire al subir o empujar.")
B.aHt=s(["Agarra la garrafa por el asa con el brazo estirado.","Codo pegado al costado.","Sube doblando el codo hasta el hombro.","Baja lento. Cambia de mano en cada serie."],t.s)
B.azr=s(["Balancear el torso."],t.s)
B.ao8=new A.cl(B.aHt,B.azr,"Suelta el aire al subir o empujar.")
B.aA6=s(["Silla firme contra la pared. Manos en el borde del asiento, dedos al frente.","Piernas estiradas (m\xe1s dif\xedcil) o dobladas (m\xe1s f\xe1cil).","Baja doblando los codos hacia atr\xe1s hasta unos 90\xb0.","Empuja hasta estirar los brazos."],t.s)
B.ayu=s(["Bajar demasiado si te molesta el hombro.","Abrir los codos hacia fuera."],t.s)
B.ao5=new A.cl(B.aA6,B.ayu,"Suelta el aire al subir o empujar.")
B.aDJ=s(["Sentado, antebrazo sobre el muslo y la mu\xf1eca por fuera de la rodilla.","Deja que la garrafa baje con la mu\xf1eca.","Sube doblando solo la mu\xf1eca.","Recorridos cortos y lentos."],t.s)
B.avZ=s(["Mover el antebrazo."],t.s)
B.anN=new A.cl(B.aDJ,B.avZ,"Suelta el aire al subir o empujar.")
B.aFN=s(["Una garrafa o mochila pesada en cada mano.","Hombros atr\xe1s y abajo, pecho arriba, abdomen firme.","Camina por la casa (o marcha en el sitio) a pasos cortos.","Aprieta las asas durante todo el tiempo marcado."],t.s)
B.axX=s(["Encorvarse hacia delante.","Inclinarse hacia un lado."],t.s)
B.ant=new A.cl(B.aFN,B.axX,"Respira corto y constante mientras caminas.")
B.aFU=s(["Posici\xf3n de flexi\xf3n, manos bajo los hombros.","Lleva una rodilla hacia el pecho y vuelve.","Alterna las piernas a buen ritmo sin subir la cadera.","Cada rodilla que llega al pecho cuenta como una repetici\xf3n."],t.s)
B.aCx=s(["Levantar la cadera.","Rebotar con los hombros."],t.s)
B.anT=new A.cl(B.aFU,B.aCx,"Respira r\xedtmico, sin aguantar el aire.")
B.aEQ=s(["Boca arriba, manos bajo la cadera y la espalda baja pegada al suelo.","Piernas estiradas y algo despegadas del suelo.","Sube y baja las piernas alternando, como unas tijeras.","Movimientos cortos y controlados."],t.s)
B.aAJ=s(["Despegar la espalda baja del suelo."],t.s)
B.any=new A.cl(B.aEQ,B.aAJ,"Suelta el aire al subir o empujar.")
B.aAB=s(["De pie, manos en la cintura.","Da un paso largo hacia atr\xe1s.",u.B,"Vuelve empujando con el pie de delante."],t.s)
B.auf=s(["Dejar que la rodilla de delante se vaya hacia dentro."],t.s)
B.ao0=new A.cl(B.aAB,B.auf,"Suelta el aire al subir o empujar.")
B.auY=s(["De espaldas a una silla firme, apoya el empeine de un pie en el asiento.","El pie de delante, a un paso largo de la silla.","Baja recto hasta que el muslo de delante quede casi paralelo.","Sube empujando con el tal\xf3n de delante."],t.s)
B.ayP=s(["Pie de delante demasiado cerca de la silla.","Inclinarse hacia un lado."],t.s)
B.anF=new A.cl(B.auY,B.ayP,"Suelta el aire al subir o empujar.")
B.aDQ=s(["Espalda pegada a la pared, pies un paso por delante.","Baja hasta que los muslos queden paralelos al suelo.","Rodillas sobre los tobillos, no por delante.","Aguanta el tiempo marcado."],t.s)
B.awL=s(["Apoyar las manos en las piernas para descargar."],t.s)
B.anO=new A.cl(B.aDQ,B.awL,"Respira lento; no aguantes el aire.")
B.azs=s(["Usa un escal\xf3n o un caj\xf3n estable, nunca una silla con ruedas.","Apoya el pie entero arriba.","Sube empujando solo con esa pierna y eleva la otra rodilla.","Baja despacio. Repite y cambia de lado."],t.s)
B.av5=s(["Impulsarse con la pierna de abajo."],t.s)
B.anW=new A.cl(B.azs,B.av5,"Suelta el aire al subir o empujar.")
B.au8=s(["Pies a la anchura de los hombros.","Baja a una sentadilla con los brazos atr\xe1s.","Salta lanzando los brazos arriba.","Aterriza suave, sobre la punta y luego el tal\xf3n, ya bajando a la siguiente."],t.s)
B.aBI=s(["Caer con las rodillas r\xedgidas.","Rodillas hacia dentro al aterrizar."],t.s)
B.anr=new A.cl(B.au8,B.aBI,"Suelta el aire al saltar.")
B.aA0=s(["Boca arriba, un pie en el suelo y la otra pierna estirada al aire.","Empuja con el tal\xf3n y sube la cadera.","Arriba, cadera recta: que no se caiga hacia un lado.","Baja despacio. Cambia de pierna."],t.s)
B.anz=new A.cl(B.aA0,B.I7,"Suelta el aire al subir o empujar.")
B.aBF=s(["Punta de un pie en el borde de un escal\xf3n; ap\xf3yate en la pared.","Baja el tal\xf3n hasta estirar.","Sube todo lo que puedas sobre la punta.","Lento arriba y abajo. Cambia de pierna."],t.s)
B.aEc=s(["Rebotar abajo."],t.s)
B.aof=new A.cl(B.aBF,B.aEc,"Suelta el aire al subir o empujar.")
B.aCX=s(["De pie, rodillas casi estiradas y manos como si sujetaras una comba.","Salta solo con los tobillos, a pocos cent\xedmetros del suelo.","Aterriza sobre la punta, sin apoyar el tal\xf3n.","Cuenta los saltos o hazlos por tiempo."],t.s)
B.aCS=s(["Doblar mucho las rodillas.","Hacer ruido al caer: aterriza suave."],t.s)
B.anK=new A.cl(B.aCX,B.aCS,"Respira r\xedtmico.")
B.auM=s(["De pie, pies juntos y brazos a los lados.","Salta abriendo las piernas y subiendo los brazos por encima de la cabeza.","Salta de nuevo para volver a cerrar.","Mant\xe9n un ritmo que puedas sostener."],t.s)
B.au9=s(["Aterrizar sobre los talones."],t.s)
B.anR=new A.cl(B.auM,B.au9,"Respira r\xedtmico, sin aguantar el aire.")
